let gradSeq=0;
export function svgArtwork(design,sideIndex,assetURLs={},fonts='',bleed=true){const product=validateDesign(design),d=dimensions(product,design.options,sideIndex),side=design.sides[sideIndex];const scale=100,W=d.width*scale,H=d.height*scale,B=bleed?d.bleed*scale:0;let body=product.group==='Apparel'&&side.background==='#ffffff'?'':`<rect x="${-B}" y="${-B}" width="${W+2*B}" height="${H+2*B}" fill="${side.background}"/>`;
 let defs='';for(const l of side.layers){const x=l.x*W,y=l.y*H,w=l.w*W,h=l.h*H;let shape='';let paint=`fill="${l.color}"`;if(l.type!=='image'&&l.type!=='line'&&l.type!=='text'&&l.outline>0)paint=`fill="none" stroke="${l.color}" stroke-width="${l.outline}"`;else if(l.gradient&&l.type!=='image'&&l.type!=='line'){const id='sg'+(++gradSeq).toString(36),a=(l.gradient.angle||0)*Math.PI/180,c=Math.cos(a)/2,s2=Math.sin(a)/2;defs+=`<linearGradient id="${id}" x1="${(.5-c).toFixed(4)}" y1="${(.5-s2).toFixed(4)}" x2="${(.5+c).toFixed(4)}" y2="${(.5+s2).toFixed(4)}"><stop offset="0" stop-color="${l.color}"/><stop offset="1" stop-color="${l.gradient.to}"/></linearGradient>`;paint=`fill="url(#${id})"`;}if(l.type==='text'){const anchor={left:'start',center:'middle',right:'end'}[l.align];const tx=x+(l.align==='center'?w/2:l.align==='right'?w:0);const f=l.fontSize*100/72;shape=`<text x="${tx}" y="${y+f}" font-family="${escape(l.font)}" font-size="${f}" font-weight="${l.bold?700:400}" font-style="${l.italic?'italic':'normal'}" ${paint} text-anchor="${anchor}"${l.spacing?` letter-spacing="${Math.round(l.spacing*f*100)/100}"`:''}>${l.text.split('\n').map((line,i)=>`<tspan x="${tx}" dy="${i?f*1.2:0}">${escape(line)}</tspan>`).join('')}</text>`;}else if(l.type==='image'){if(assetURLs[l.assetId])shape=`<image x="${x}" y="${y}" width="${w}" height="${h}" href="${escape(assetURLs[l.assetId])}" preserveAspectRatio="${l.fit==='cover'?'xMidYMid slice':'xMidYMid meet'}"/>`;}else if(l.type==='rect'){const o=l.outline>0?l.outline/2:0;shape=`<rect x="${x+o}" y="${y+o}" width="${Math.max(0,w-2*o)}" height="${Math.max(0,h-2*o)}" rx="${Math.min(w,h)*(l.radius??(l.rounded?.15:0))}" ${paint}/>`;}else if(l.type==='shape')shape=l.outline>0?`<path d="${SHAPES[l.shape]}" transform="translate(${x} ${y}) scale(${w/100} ${h/100})" fill="none" stroke="${l.color}" stroke-width="${l.outline*100/Math.max(1e-6,Math.min(w,h))}"/>`:`<path d="${SHAPES[l.shape]}" transform="translate(${x} ${y}) scale(${w/100} ${h/100})" ${paint} fill-rule="${NONZERO_SHAPES.includes(l.shape)?'nonzero':'evenodd'}"/>`;else if(l.type==='circle'){const o=l.outline>0?l.outline/2:0;shape=`<ellipse cx="${x+w/2}" cy="${y+h/2}" rx="${Math.max(0,w/2-o)}" ry="${Math.max(0,h/2-o)}" ${paint}/>`;}else shape=`<line x1="${x}" y1="${y}" x2="${x+w}" y2="${y+h}" stroke="${l.color}" stroke-width="${Math.max(.5,l.stroke||2)}"/>`;body+=`<g opacity="${l.opacity}" transform="rotate(${l.rotation} ${x+w/2} ${y+h/2})">${shape}</g>`;}
 return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${d.width+2*(bleed?d.bleed:0)}in" height="${d.height+2*(bleed?d.bleed:0)}in" viewBox="${-B} ${-B} ${W+2*B} ${H+2*B}"><defs><style>${fonts}</style>${defs}</defs>${body}</svg>`;
}
